const updateActivity = `-- name: UpdateActivity :one
UPDATE activities
SET title         = $2,
    description   = $3,
    activity_type = $4,
    recurrence    = $5,
    priority      = $6,
    kind          = $7,
    owner         = $8,
    assignee_id   = $9,
    due_date      = $10,
    status        = CASE
                        WHEN $10::date < CURRENT_DATE AND status IN ('planned', 'in_progress')
                            THEN 'overdue'
                        WHEN ($10 IS NULL OR $10::date >= CURRENT_DATE) AND status = 'overdue'
                            THEN 'planned'
                        ELSE status
                    END,
    updated_at    = NOW()
WHERE id = $1
RETURNING id, measure_id, title, description, activity_type, recurrence, status, owner, due_date, completed_at, completed_by, notes, evidence_url, parent_activity_id, created_at, updated_at, assignee_id, priority, kind, ref_num
`

type UpdateActivityParams struct {
	ID           uuid.UUID     `json:"id"`
	Title        string        `json:"title"`
	Description  string        `json:"description"`
	ActivityType string        `json:"activity_type"`
	Recurrence   string        `json:"recurrence"`
	Priority     string        `json:"priority"`
	Kind         string        `json:"kind"`
	Owner        string        `json:"owner"`
	AssigneeID   uuid.NullUUID `json:"assignee_id"`
	DueDate      sql.NullTime  `json:"due_date"`
}

func (q *Queries) UpdateActivity(ctx context.Context, arg UpdateActivityParams) (Activity, error) {
	row := q.db.QueryRowContext(ctx, updateActivity,
		arg.ID,
		arg.Title,
		arg.Description,
		arg.ActivityType,
		arg.Recurrence,
		arg.Priority,
		arg.Kind,
		arg.Owner,
		arg.AssigneeID,
		arg.DueDate,
	)
	var i Activity
	err := row.Scan(
		&i.ID,
		&i.MeasureID,
		&i.Title,
		&i.Description,
		&i.ActivityType,
		&i.Recurrence,
		&i.Status,
		&i.Owner,
		&i.DueDate,
		&i.CompletedAt,
		&i.CompletedBy,
		&i.Notes,
		&i.EvidenceUrl,
		&i.ParentActivityID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.AssigneeID,
		&i.Priority,
		&i.Kind,
		&i.RefNum,
	)
	return i, err
}

